<span class="line"><span style="color:#A626A4;">    let</span><span style="color:#383A42;"> a </span><span style="color:#0184BC;">=</span><span style="color:#383A42;"> computedStyle.</span><span style="color:#E45649;">marginTop</span><span style="color:#383A42;">; </span><span style="color:#A0A1A7;font-style:italic;">// Отступ в пикселях</span></span>
