<span class="line"><span style="color:#4078F2;">  getComputedStyle</span><span style="color:#383A42;">(box).</span><span style="color:#E45649;">transform</span><span style="color:#383A42;">; </span><span style="color:#A0A1A7;font-style:italic;">// +++</span></span>
